def molecular_weight(formula):
    atomic_weights = {'H': 1.01, 'C': 12.01, 'N': 14.01, 'O': 16.00, 'Na': 22.99}
    total_weight = 0
    element = ''
    count = ''
    for char in formula:
        if char.isupper():
            if element:
                total_weight += atomic_weights[element] * (int(count) if count else 1)
            element = char
            count = ''
        elif char.islower():
            element += char
        elif char.isdigit():
            count += char
    if element:
        total_weight += atomic_weights[element] * (int(count) if count else 1)
    return round(total_weight, 2)
```

