def calculate_molecular_weight(substance):
    # Define the atomic weights
    atomic_weights = {
        'H': 1.01,
        'N': 14.01,
        'O': 16.00,
        'Na': 22.99
    }
    # Define the substance composition
    substance_composition = {
        'NH4OH': {'H': 5, 'N': 1, 'O': 1},
        'NaHCO3': {'Na': 1, 'H': 1, 'C': 1, 'O': 3}
    }
    # Calculate the molecular weight
    molecular_weight = sum(atomic_weights[atom] * count for atom, count in substance_composition[substance].items())
    return round(molecular_weight, 2)

